  OrdersController_create: {
    parameters: {
      query?: never;
      header?: {
        /** @description Uma chave por tentativa de compra (até 255 caracteres ASCII visíveis). Repetida com o mesmo corpo, devolve o pedido já criado com o header `Idempotent-Replayed: true`; com outro corpo, 422. */
        'Idempotency-Key'?: string;
      };
      path?: never;
      cookie?: never;
    };
    requestBody: {
      content: {
        'application/json': {
          items: {
            /**
             * Format: uuid
             * @example 0193a4f2-7c1e-7b3d-9a51-3f0c2d8e4b61
             */
            ticketTypeId: string;
            /** @example 2 */
            quantity: number;
          }[];
        };
      };
    };
    responses: {
      /** @description Pedido PENDING com o estoque reservado até `expiresAt` e a página de pagamento do Stripe em `checkoutUrl`. No replay, o pedido como está agora; `checkoutUrl` é nulo se ele não pode mais ser pago. */
      201: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': {
            /** Format: uuid */
            id: string;
            /** @enum {string} */
            status:
              | 'PENDING'
              | 'PROCESSING'
              | 'PAID'
              | 'EXPIRED'
              | 'CANCELLED'
              | 'REFUND_PENDING'
              | 'REFUNDED';
            totalCents: number;
            /** @enum {string} */
            currency: 'BRL';
            /** Format: date-time */
            expiresAt: string;
            /** Format: date-time */
            createdAt: string;
            items: {
              /** Format: uuid */
              ticketTypeId: string;
              quantity: number;
              unitPriceCents: number;
            }[];
            /**
             * Format: uri
             * @example https://checkout.stripe.com/c/pay/cs_test_a1
             */
            checkoutUrl: string | null;
          };
        };
      };
      /** @description Sem estoque, vendas fechadas ou evento fora de venda. */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Acima do limite por pedido do lote, total grande demais ou chave repetida. */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description Mais de 20 pedidos por minuto deste usuário. */
      429: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description O Stripe falhou ao criar a sessão: o pedido foi cancelado e o estoque voltou. */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
    };
  };
